	if j1.Stats["new"] != 2 {
		t.Fatalf("first sync new=%d, want 2 (err=%s)", j1.Stats["new"], j1.Error)
	}
	for i := 0; i < 2; i++ {
		j := syncAndWait(t, app, acc.ID)
		if j.Stats["new"] != 0 || j.Stats["duplicate"] != 2 {
			t.Fatalf("resync %d: new=%d dup=%d, want 0/2", i, j.Stats["new"], j.Stats["duplicate"])
