func isConnectionLost(err error) bool {
	var nerr net.Error
	return errors.Is(err, io.EOF) || errors.Is(err, net.ErrClosed) ||
		(errors.As(err, &nerr) && nerr.Timeout()) ||
		strings.Contains(err.Error(), "connection reset")
}

