name: Release

# Push a semver tag (e.g. v0.3.1) to build the offline artifacts and publish a
# GitHub Release. Mirrors the manual recipe in dist/README.md so releases are
# reproducible: static binary + docker-load image tarball + SBOM + checksums.
on:
  push:
    tags: ["v*"]

permissions:
  contents: write

env:
  GO_VERSION: "1.26.6"   # 1.26.6 에서 GO-2026-6218(net/url)·GO-2026-6091(html/template) 이 고쳐졌다
  NODE_VERSION: "22"

jobs:
  release:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: ${{ env.NODE_VERSION }}
          check-latest: true
          cache: npm
          cache-dependency-path: web/package-lock.json
      - uses: actions/setup-go@v5
        with:
          go-version: ${{ env.GO_VERSION }}
          check-latest: true

      - name: Derive version
        id: v
        run: |
          TAG="${GITHUB_REF_NAME}"        # e.g. v0.3.1
          echo "tag=$TAG"        >> "$GITHUB_OUTPUT"
          echo "num=${TAG#v}"    >> "$GITHUB_OUTPUT"   # 0.3.1

      - name: Rebuild embedded browser assets
        working-directory: web
        run: |
          npm ci --no-audit --no-fund
          npm run build

      - name: Verify release browser assets are current
        run: |
          if [ -n "$(git status --porcelain --untracked-files=all -- internal/transport/spa/assets)" ]; then
            git status --short -- internal/transport/spa/assets
            echo "The release tag must include current /app assets. Run make frontend before tagging." >&2
            exit 1
          fi

      - name: Build static binary
        run: |
          mkdir -p dist
          CGO_ENABLED=0 GOOS=linux GOARCH=amd64 go build -trimpath \
            -ldflags="-s -w \
              -X postra/internal/platform/build.Version=${{ steps.v.outputs.tag }} \
              -X postra/internal/platform/build.Commit=${{ github.sha }} \
              -X postra/internal/platform/build.BuildTime=$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
            -o dist/postra-${{ steps.v.outputs.num }}-linux-amd64 ./cmd/postra

      - name: Build offline image tarball
        run: |
          go run scripts/mkimage.go \
            dist/postra-${{ steps.v.outputs.num }}-linux-amd64 \
            dist/postra-${{ steps.v.outputs.num }}.tar \
            postra:${{ steps.v.outputs.num }} \
            ${{ steps.v.outputs.tag }} \
            ${{ github.sha }}
          gzip -9 -f dist/postra-${{ steps.v.outputs.num }}.tar

      - name: Generate SBOM
        run: |
          go install github.com/CycloneDX/cyclonedx-gomod/cmd/cyclonedx-gomod@v1.10.0
          cyclonedx-gomod app -json -output dist/postra-${{ steps.v.outputs.num }}-sbom.cdx.json -main cmd/postra .

      - name: Generate browser SBOM
        working-directory: web
        run: npm sbom --sbom-format=cyclonedx --omit=dev --package-lock-only > ../dist/postra-${{ steps.v.outputs.num }}-frontend-sbom.cdx.json

      - name: Checksums
        working-directory: dist
        run: |
          sha256sum \
            postra-${{ steps.v.outputs.num }}-linux-amd64 \
            postra-${{ steps.v.outputs.num }}.tar.gz \
            postra-${{ steps.v.outputs.num }}-sbom.cdx.json \
            postra-${{ steps.v.outputs.num }}-frontend-sbom.cdx.json > SHA256SUMS.txt

      - name: Publish release
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          notes_file="docs/releases/${{ steps.v.outputs.tag }}.md"
          if [ -f "$notes_file" ]; then
            notes_args=(--notes-file "$notes_file")
          else
            notes_args=(--generate-notes)
          fi
          gh release create "${{ steps.v.outputs.tag }}" \
            --title "Postra ${{ steps.v.outputs.tag }}" \
            "${notes_args[@]}" \
            dist/postra-${{ steps.v.outputs.num }}-linux-amd64 \
            dist/postra-${{ steps.v.outputs.num }}.tar.gz \
            dist/postra-${{ steps.v.outputs.num }}-sbom.cdx.json \
            dist/postra-${{ steps.v.outputs.num }}-frontend-sbom.cdx.json \
            dist/SHA256SUMS.txt
